<?php

declare(strict_types=1);

use EventMenu\Core\Auth;use EventMenu\Core\Crypto;use EventMenu\Core\Database;use EventMenu\Core\Security;use EventMenu\Services\GatewayService;
Auth::requirePermission('gateways.manage');$tenantId=em_require_tenant();
if($_SERVER['REQUEST_METHOD']==='POST'){em_post_csrf();$action=(string)($_POST['action']??'');if($action==='gateway-save'){$provider=(string)($_POST['provider']??'');if(!in_array($provider,['stripe','pagbank','mercadopago'],true))exit('Gateway inválido.');$stmt=$pdo->prepare('SELECT * FROM payment_gateways WHERE tenant_id=? AND provider=?');$stmt->execute([$tenantId,$provider]);$existing=$stmt->fetch();$config=$existing?Crypto::decryptJson($existing['config_encrypted']):[];foreach(['secret_key','access_token','token','api_base','tap_on_app_key','tap_on_app_name','tap_on_app_version','legacy_email','legacy_token','tap_on_query_base']as$key){$value=trim((string)($_POST[$key]??''));if($value!=='')$config[$key]=$value;}if(in_array($provider,['pagbank','mercadopago'],true)){$config['pix_enabled']=isset($_POST['pix_enabled']);$config['pix_default']=isset($_POST['pix_default']);$config['pix_priority']=max(1,min(999,(int)($_POST['pix_priority']??100)));if($config['pix_default']){$config['pix_enabled']=true;$others=$pdo->prepare('SELECT id,config_encrypted FROM payment_gateways WHERE tenant_id=? AND provider IN ("pagbank","mercadopago") AND provider<>?');$others->execute([$tenantId,$provider]);foreach($others->fetchAll()as$other){$oc=Crypto::decryptJson((string)$other['config_encrypted']);$oc['pix_default']=false;$pdo->prepare('UPDATE payment_gateways SET config_encrypted=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND tenant_id=?')->execute([Crypto::encryptJson($oc),(int)$other['id'],$tenantId]);}}}if($provider==='pagbank')$config['tap_on_tax_pass_through']=isset($_POST['tap_on_tax_pass_through']);$account=trim((string)($_POST['account_reference']??($existing['account_reference']??'')));$webhook=trim((string)($_POST['webhook_secret']??''));try{(new GatewayService())->save($provider,$account,$config,$webhook,isset($_POST['active']));em_flash('ok','Configuração de pagamento salva com segurança.');}catch(Throwable $e){em_flash('error',$e->getMessage());}em_go('gateways');}}
$tenant=$pdo->prepare('SELECT slug FROM tenants WHERE id=?');$tenant->execute([$tenantId]);$tenantSlug=(string)$tenant->fetchColumn();$g=$pdo->prepare('SELECT id,provider,account_reference,config_encrypted,active FROM payment_gateways WHERE tenant_id=? ORDER BY provider');$g->execute([$tenantId]);$gateways=[];$configs=[];foreach($g->fetchAll()as$row){$gateways[$row['provider']]=$row;$configs[$row['provider']]=Crypto::decryptJson($row['config_encrypted']);}$providerLabels=['stripe'=>'Stripe','pagbank'=>'PagBank','mercadopago'=>'Mercado Pago'];em_header('Pagamentos e NFC','gateways');?>
<section class="page-hero"><div><span class="eyebrow">PAGAMENTOS</span><h2>Conexões e recebimentos</h2><p>Ative os provedores usados pela empresa e escolha qual conta será a principal para PIX.</p></div><div class="hero-actions"><a class="button secondary" href="<?=Security::e(app_url('?route=payments'))?>">Ver transações</a></div></section>
<section class="gateway-overview"><?php foreach($providerLabels as$provider=>$label):$row=$gateways[$provider]??null;$cfg=$configs[$provider]??[];?><article class="gateway-status-card"><div class="gateway-provider-icon"><?=Security::e(mb_substr($label,0,1))?></div><div><strong><?=Security::e($label)?></strong><span><?=$row&&$row['active']?'Conectado e ativo':'Não habilitado'?><?=!empty($cfg['pix_default'])?' · PIX principal':(!empty($cfg['pix_enabled'])?' · PIX ativo':'')?></span></div><b class="connection-dot <?=$row&&$row['active']?'online':''?>"></b></article><?php endforeach;?></section>
<section class="gateway-config-list"><?php foreach($providerLabels as$provider=>$label):$row=$gateways[$provider]??null;$cfg=$configs[$provider]??[];$pix=in_array($provider,['pagbank','mercadopago'],true);$pixEnabled=$pix?(!array_key_exists('pix_enabled',$cfg)||(bool)$cfg['pix_enabled']):false;?><details class="card gateway-config-card"><summary><span><b><?=Security::e($label)?></b><small><?=$row&&$row['active']?'Ativo':'Inativo'?></small></span><span class="gateway-config-action">Configurar</span></summary><form method="post" class="form-grid gateway-form"><input type="hidden" name="_csrf" value="<?=em_csrf()?>"><input type="hidden" name="action" value="gateway-save"><input type="hidden" name="provider" value="<?=Security::e($provider)?>"><label class="span-2"><?=$provider==='stripe'?'Account ID (acct_...)':($provider==='mercadopago'?'Collector ID':'Referência da conta PagBank')?><input name="account_reference" value="<?=Security::e($row['account_reference']??'')?>" required></label><?php if($provider==='stripe'):?><label class="span-2">Secret key<input type="password" name="secret_key" placeholder="Deixe vazio para manter a atual"></label><?php elseif($provider==='mercadopago'):?><label class="span-2">Access token<input type="password" name="access_token" placeholder="Deixe vazio para manter o atual"></label><?php else:?><label class="span-2">Token PagBank<input type="password" name="token" placeholder="Deixe vazio para manter o atual"></label><label class="span-2">API base<input name="api_base" value="<?=Security::e((string)($cfg['api_base']??''))?>" placeholder="https://api.pagseguro.com"></label><?php endif;?><?php if($pix):?><div class="span-2 card" style="padding:14px"><strong>PIX</strong><p class="muted">QR Code e Copia e Cola são gerados dentro do EventMenu. A confirmação do pagamento permanece no servidor.</p><label class="checkbox"><input type="checkbox" name="pix_enabled"<?=$pixEnabled?' checked':''?>> Aceitar PIX por <?=Security::e($label)?></label><label class="checkbox"><input type="checkbox" name="pix_default"<?=!empty($cfg['pix_default'])?' checked':''?>> Usar como PIX principal</label><label>Prioridade<input type="number" min="1" max="999" name="pix_priority" value="<?=max(1,(int)($cfg['pix_priority']??100))?>"><small>Menor número = maior prioridade.</small></label></div><?php endif;?><?php if($provider==='pagbank'):?><details class="span-2 gateway-advanced"><summary>Tap On / NFC Android</summary><div class="form-grid"><label class="span-2">AppKey Tap On<input type="password" name="tap_on_app_key" placeholder="Deixe vazio para manter a atual"></label><label>Nome do app<input name="tap_on_app_name" value="<?=Security::e((string)($cfg['tap_on_app_name']??'EventMenu'))?>"></label><label>Versão do app<input name="tap_on_app_version" value="<?=Security::e((string)($cfg['tap_on_app_version']??'1.0.0'))?>"></label><label class="span-2">E-mail da conta para consulta<input type="email" name="legacy_email" value="<?=Security::e((string)($cfg['legacy_email']??''))?>"></label><label class="span-2">Token de consulta Tap On<input type="password" name="legacy_token" placeholder="Deixe vazio para manter o atual"></label><label class="span-2">Endpoint de consulta<input name="tap_on_query_base" value="<?=Security::e((string)($cfg['tap_on_query_base']??''))?>"></label><label class="checkbox span-2"><input type="checkbox" name="tap_on_tax_pass_through"<?=em_checked($cfg['tap_on_tax_pass_through']??false)?>> Permitir repasse de taxas no Tap On</label></div></details><?php endif;?><label class="span-2">Segredo do webhook<input type="password" name="webhook_secret" placeholder="Deixe vazio para manter o atual"></label><label class="checkbox span-2"><input type="checkbox" name="active"<?=em_checked($row['active']??0)?>> Gateway ativo</label><button class="primary span-2">Salvar <?=Security::e($label)?></button></form><details class="technical-details gateway-webhook"><summary>Webhook desta integração</summary><code><?=Security::e(app_absolute_url('webhook.php?provider='.$provider.'&tenant='.urlencode($tenantSlug)))?></code></details></details><?php endforeach;?></section>
<section class="card" style="margin-top:16px"><div class="section-head"><div><span class="eyebrow">TAP ON</span><h2>NFC PagBank</h2><p class="muted">A configuração NFC continua separada do PIX e não foi alterada nesta etapa.</p></div></div><a class="button secondary" href="<?=Security::e(app_url('?route=gateways'))?>">Atualizar status</a></section>
<?php em_footer();